function normalizar(texto) {
    return texto.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

// Fuzzy match: todas las palabras del query deben aparecer en el texto (en cualquier orden)
function matchFuzzy(textoNorm, queryNorm) {
    const palabras = queryNorm.split(/\s+/).filter(Boolean);
    return palabras.every(p => textoNorm.includes(p));
}

window.addEventListener('load', () => {
    const buscador = document.getElementById("search-input");
    const btnBuscar = document.getElementById("search-btn");
    const provincias = document.querySelectorAll("svg path");

    function ejecutarBusqueda() {
        const busqueda = normalizar(buscador.value.trim());
        let label = document.getElementById("mapa-label");
        if (busqueda !== "") {
            if (!label) {
                label = document.createElement("div");
                label.id = "mapa-label";
                label.textContent = "↓ Selecciona la provincia";
                document.querySelector("svg").insertAdjacentElement("beforebegin", label);
            }
        } else {
            if (label) label.remove();
        }
        provincias.forEach(prov => {
            const lista = datosns[prov.id];
            if (busqueda !== "" && lista && lista.some(c => matchFuzzy(normalizar(c.c), busqueda))) {
                prov.style.fill = "#00d2ff";
            } else {
                prov.style.fill = "#1a1a2e";
            }
        });
        if (busqueda === "") cerrarPopup();
    }

    // Búsqueda en tiempo real al escribir
    buscador.addEventListener("input", ejecutarBusqueda);
    btnBuscar.addEventListener("click", ejecutarBusqueda);
    buscador.addEventListener("keydown", e => { if (e.key === "Enter") ejecutarBusqueda(); });

    provincias.forEach(prov => {
        prov.style.cursor = "pointer";
        prov.addEventListener("click", function (e) {
            const busqueda = normalizar(buscador.value.trim());
            if (busqueda === "") return;
            const lista = datosns[prov.id];
            if (!lista || lista.length === 0) return;
            const resultados = lista.filter(c => matchFuzzy(normalizar(c.c), busqueda));
            if (resultados.length === 0) return;
            mostrarPopup(e, prov.getAttribute("name") || prov.id, resultados);
        });
    });

    function mostrarPopup(event, nombreProvincia, resultados) {
        cerrarPopup();
        const popup = document.createElement("div");
        popup.id = "mapa-popup";
        popup.style.left = Math.min(event.clientX + 14, window.innerWidth - 360) + "px";
        popup.style.top = Math.min(event.clientY + 14, window.innerHeight - 440) + "px";
        popup.innerHTML = `
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
                <div style="display:flex;align-items:center;gap:8px;">
                    <span class="material-symbols-outlined" style="font-size:18px;color:var(--naranja-neon);">location_on</span>
                    <strong style="font-size:15px;color:var(--azul-neon);text-transform:uppercase;letter-spacing:1px;">${nombreProvincia}</strong>
                </div>
                <button id="popup-cerrar" style="background:none;border:none;cursor:pointer;color:var(--texto-secundario);padding:2px;border-radius:6px;">
                    <span class="material-symbols-outlined" style="font-size:20px;">close</span>
                </button>
            </div>
            <div style="height:1px;background:var(--border);margin-bottom:10px;"></div>`;
        popup.querySelector("#popup-cerrar").addEventListener("click", cerrarPopup);
        resultados.forEach(item => {
            const tienen = item.n && item.n !== 'No disponible' && item.n > 5;
            const nHTML = tienen
                ? `<span style="background:rgba(0,210,255,0.12);color:var(--azul-neon);padding:3px 10px;border-radius:20px;font-size:12px;font-weight:600;white-space:nowrap;border:1px solid rgba(0,210,255,0.3);">${item.n}</span>`
                : `<span style="background:rgba(255,255,255,0.05);color:var(--texto-secundario);padding:3px 10px;border-radius:20px;font-size:12px;">Sin corte</span>`;
            const fila = document.createElement("div");
            fila.style.cssText = "padding:9px 0;border-bottom:1px solid rgba(0,210,255,0.08);";
            fila.innerHTML = `
                <div style="font-size:13px;font-weight:600;color:var(--texto-principal);margin-bottom:5px;">${item.c}</div>
                <div style="display:flex;justify-content:space-between;align-items:center;">
                    <div style="display:flex;align-items:center;gap:5px;">
                        <span class="material-symbols-outlined" style="font-size:15px;color:var(--naranja-neon);">school</span>
                        <span style="font-size:12px;color:var(--texto-secundario);">${item.u}</span>
                    </div>
                    ${nHTML}
                </div>`;
            popup.appendChild(fila);
        });
        document.body.appendChild(popup);
        setTimeout(() => { document.addEventListener("click", cerrarAlFuera); }, 100);
    }

    function cerrarAlFuera(e) {
        const popup = document.getElementById("mapa-popup");
        if (popup && !popup.contains(e.target)) cerrarPopup();
    }

    function cerrarPopup() {
        const popup = document.getElementById("mapa-popup");
        if (popup) popup.remove();
        document.removeEventListener("click", cerrarAlFuera);
    }
});